// GPUI/Tailwind-style fluent builder API: traits with default methods that return Self and mutate a
// style accessed via `fn style(&mut self) -> &mut StyleRefinement`, generated by a macro.
use std::fmt::Write;

#[derive(Default, Debug, Clone, PartialEq)]
struct Style {
    flex: Option<bool>,
    direction: Option<&'static str>,
    padding: Option<f32>,
    margin: Option<f32>,
    gap: Option<f32>,
    width: Option<Length>,
    bg: Option<u32>,
    rounded: Option<f32>,
    border: Option<f32>,
    items_center: bool,
    justify: Option<&'static str>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Length {
    Px(f32),
    Rems(f32),
    Fraction(f32),
    Auto,
}

trait Styled: Sized {
    fn style(&mut self) -> &mut Style;

    fn flex(mut self) -> Self {
        self.style().flex = Some(true);
        self
    }
    fn flex_row(mut self) -> Self {
        self.style().direction = Some("row");
        self.flex()
    }
    fn flex_col(mut self) -> Self {
        self.style().direction = Some("col");
        self.flex()
    }
    fn items_center(mut self) -> Self {
        self.style().items_center = true;
        self
    }
    fn justify_between(mut self) -> Self {
        self.style().justify = Some("between");
        self
    }
    fn w(mut self, l: Length) -> Self {
        self.style().width = Some(l);
        self
    }
    fn w_full(self) -> Self {
        self.w(Length::Fraction(1.0))
    }
    fn w_auto(self) -> Self {
        self.w(Length::Auto)
    }
    fn bg(mut self, c: u32) -> Self {
        self.style().bg = Some(c);
        self
    }
    fn border_1(mut self) -> Self {
        self.style().border = Some(1.0);
        self
    }
}

// Generate spacing methods p_1, p_2 ... m_1 ... gap_1 ..., like gpui's style macros.
macro_rules! spacing_methods {
    ($( $field:ident : [ $( $name:ident = $val:expr ),* ] ),* $(,)?) => {
        trait Spacing: Styled {
            $( $(
                fn $name(mut self) -> Self {
                    self.style().$field = Some($val * 4.0);
                    self
                }
            )* )*
        }
        impl<T: Styled> Spacing for T {}
    };
}

spacing_methods! {
    padding: [p_0 = 0.0, p_1 = 1.0, p_2 = 2.0, p_4 = 4.0],
    margin: [m_1 = 1.0, m_2 = 2.0],
    gap: [gap_1 = 1.0, gap_2 = 2.0, gap_3 = 3.0],
    rounded: [rounded_sm = 0.5, rounded_md = 1.5],
}

struct Div {
    id: Option<&'static str>,
    style: Style,
    children: Vec<Node>,
}
enum Node {
    Div(Div),
    Text(String),
}

impl Styled for Div {
    fn style(&mut self) -> &mut Style {
        &mut self.style
    }
}

fn div() -> Div {
    Div { id: None, style: Style::default(), children: vec![] }
}

impl Div {
    fn id(mut self, id: &'static str) -> Self {
        self.id = Some(id);
        self
    }
    fn child(mut self, d: Div) -> Self {
        self.children.push(Node::Div(d));
        self
    }
    fn text(mut self, s: impl Into<String>) -> Self {
        self.children.push(Node::Text(s.into()));
        self
    }
    fn map<F: FnOnce(Self) -> Self>(self, f: F) -> Self {
        f(self)
    }
}

fn describe_style(s: &Style) -> String {
    let mut out = String::new();
    if let Some(d) = s.direction {
        write!(out, " flex-{}", d).unwrap();
    } else if s.flex == Some(true) {
        out.push_str(" flex");
    }
    if s.items_center {
        out.push_str(" items-center");
    }
    if let Some(j) = s.justify {
        write!(out, " justify-{}", j).unwrap();
    }
    for (n, v) in [("p", s.padding), ("m", s.margin), ("gap", s.gap), ("rounded", s.rounded), ("border", s.border)] {
        if let Some(v) = v {
            write!(out, " {}={}", n, v).unwrap();
        }
    }
    match s.width {
        Some(Length::Px(p)) => write!(out, " w={}px", p).unwrap(),
        Some(Length::Rems(r)) => write!(out, " w={}rem", r).unwrap(),
        Some(Length::Fraction(f)) => write!(out, " w={}%", f * 100.0).unwrap(),
        Some(Length::Auto) => out.push_str(" w=auto"),
        None => {}
    }
    if let Some(c) = s.bg {
        write!(out, " bg=#{:06x}", c).unwrap();
    }
    out
}

fn print_tree(n: &Node, depth: usize) {
    let pad = "  ".repeat(depth);
    match n {
        Node::Text(t) => println!("{}{:?}", pad, t),
        Node::Div(d) => {
            println!("{}div{}{}", pad, d.id.map(|i| format!("#{}", i)).unwrap_or_default(), describe_style(&d.style));
            for c in &d.children {
                print_tree(c, depth + 1);
            }
        }
    }
}

fn title_bar(title: &str, dirty: bool) -> Div {
    div()
        .id("titlebar")
        .flex_row()
        .justify_between()
        .items_center()
        .w_full()
        .p_1()
        .bg(0x2b2d30)
        .child(div().text(title.to_string()))
        .map(|d| if dirty { d.child(div().rounded_sm().bg(0xffcc00).text("●")) } else { d })
}

fn main() {
    let ui = div()
        .id("root")
        .flex_col()
        .gap_2()
        .w(Length::Px(800.0))
        .child(title_bar("main.rs", true))
        .child(
            div()
                .flex_row()
                .gap_1()
                .child(div().id("sidebar").w(Length::Rems(16.0)).p_2().border_1().text("files"))
                .child(div().id("editor").w_auto().p_4().m_1().rounded_md().text("fn main() {}").text("// cursor")),
        )
        .child(title_bar("status", false).p_0().m_2().gap_3());
    print_tree(&Node::Div(ui), 0);
    let a = div().p_1().p_2();
    let b = div().p_2();
    println!("last write wins: {}", a.style == b.style);
}
